// Samlet utforskingsskisse. Den isolerte regelbyggeren og kalenderen deler én maltilstand.
const priorSidebar=sidebar,priorRender=render,priorExpandedQueue=expandedQueue,priorDocumentsView=documentsView,priorSharingView=sharingView;
let workingYear=2026,yearTab='frister',moduleSnapshot=null,moduleReady=false,nextModuleTab=null,nextSettingsTab=null;
const moduleFrame=document.createElement('iframe');moduleFrame.id='templateFrame';moduleFrame.className='template-frame';moduleFrame.title='Årsmal og administrator-innstillinger';moduleFrame.hidden=true;moduleFrame.src='aarsmal/prototype-aarsmal.html?embedded=1';$('main').append(moduleFrame);
const ADMIN_SECTIONS=[['year','Budsjettår og frister'],['template','Årsmal'],['groups','Grupper og innsyn'],['sharing','Eksport og deling'],['internal','Internkalender'],['settings','Administrator-innstillinger']];
section='year';
sidebar=function(){if(area!=='admin'){priorSidebar();return}document.body.dataset.area=area;$('sidebar').innerHTML='<p class="eyebrow">Forvaltning</p><h2>Administrasjon</h2>'+ADMIN_SECTIONS.map(([key,title])=>`<button type="button" class="side-button ${section===key?'active':''}" data-section="${key}">${title}${key==='year'&&proposals.length?'<span class="side-count">'+proposals.length+'</span>':''}</button>`).join('')};
function normalizeAdminSection(){if(section==='queue'){section='year';yearTab='queue'}if(section==='register'){section='year';yearTab='frister'}if(section==='documents'){section='year';yearTab='documents'}if(section==='phases'){section='settings';nextSettingsTab='phases'}}
function syncModule(){const show=isAdmin&&area==='admin'&&['template','settings'].includes(section);moduleFrame.hidden=!show;if(show&&moduleReady){moduleFrame.contentWindow.postMessage({type:'atelier:show',area:section,tab:nextModuleTab,settingsTab:nextSettingsTab},'*');nextModuleTab=null;nextSettingsTab=null}}
render=function(){if(area==='admin')normalizeAdminSection();priorRender();syncModule()};
expandedAdminView=function(){if(!isAdmin)return '';if(section==='year')return workYearView();if(['template','settings'].includes(section))return '';if(section==='groups')return groupsView();if(section==='sharing')return sharingView();if(section==='internal')return internalView();return ''};
function stripHeading(html,removeTabs=false){const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.heading')?.remove();if(removeTabs)t.content.querySelector('.local-tabs')?.remove();return t.innerHTML}
function yearQueue(){const all=proposals;try{proposals=all.filter(p=>p.budgetYear===workingYear);return stripHeading(priorExpandedQueue())}finally{proposals=all}}
function yearDocuments(){documentBudgetYear=workingYear;moduleTabs.documents='upload';const t=document.createElement('template');t.innerHTML=stripHeading(priorDocumentsView(),true);t.content.querySelector('[name=documentYear]')?.closest('.field')?.remove();return t.innerHTML}
function workYearView(){focusYear=workingYear;generationYear=workingYear;const selected=records.filter(r=>r.published&&r.budgetYear===workingYear&&r.title.toLocaleLowerCase('nb').includes(registrySearch.toLocaleLowerCase('nb'))),counts=proposals.filter(p=>p.budgetYear===workingYear).length,others=[...new Set(proposals.filter(p=>p.budgetYear!==workingYear).map(p=>p.budgetYear))];return header('Budsjettår og frister','Vedlikehold de konkrete fristene for ett budsjettår.',adminActions())+`<div class="working-year"><label for="workingYear">Du arbeider med budsjettåret</label><select id="workingYear">${[2026,2027,2028].map(y=>`<option ${y===workingYear?'selected':''}>${y}</option>`).join('')}</select><span class="hint">Fristens kalenderdato kan falle i et annet år.</span></div>${others.length?'<div class="other-years">Forslag venter også i '+others.map(y=>`<button type="button" data-work-year="${y}">${y} · ${proposals.filter(p=>p.budgetYear===y).length} forslag</button>`).join('')+'</div>':''}<nav class="year-admin-tabs" aria-label="Arbeid med budsjettåret">${[['frister','Frister'],['queue','Forslag'],['documents','Dokumenter'],['generate','Generer fra årsmal']].map(([key,title])=>`<button type="button" data-year-tab="${key}" aria-pressed="${yearTab===key}">${title}${key==='queue'&&counts?'<span class="small-count">'+counts+'</span>':''}</button>`).join('')}</nav>${yearTab==='frister'?`<section class="surface"><div class="year-summary"><h2>Frister for budsjettåret ${workingYear}</h2><label><input type="search" id="yearRegistrySearch" aria-label="Søk i årets frister" placeholder="Søk i frister" value="${esc(registrySearch)}"></label></div><section class="canvas">${listMarkup(selected)}</section><p class="work-year-note">${selected.length} publiserte frister. Samme fristobjekter vises i Kalender og Budsjettår.</p></section>`:yearTab==='queue'?yearQueue():yearTab==='documents'?yearDocuments():generationView()}`}
generationView=function(){const items=generated.filter(g=>g.budgetYear===workingYear);return `<section class="surface"><h2>Bruk årsmalen på budsjettåret ${workingYear}</h2><p>Beregningen bruker de lagrede reglene fra Årsmal, inkludert ukedager, datovindu, avhengigheter og valgårsvalg.</p><div class="row-actions"><button type="button" class="primary" data-compute-year>${items.some(g=>g.status==='open')?'Beregn på nytt':'Beregn forslag'}</button><button type="button" data-template-preview>Se reglene og prøv ankerdatoer</button></div><p class="hint" style="margin-top:14px">Dette publiserer ingen frister. Årets åpne genererte forslag erstattes ved ny beregning; publiserte frister og løpende forslag beholdes.</p></section>${items.length?`<section class="surface generated-preview"><h2>Forslag til behandling · ${workingYear}</h2>${items.map(g=>`<div class="module-card"><div><strong>${esc(g.title)}</strong><p>${g.error?esc(g.error):esc(fullDate(g))}</p><span class="state-pill ${g.error||g.precision==='month'?'warn':''}">${g.error?'Kan ikke beregnes':g.status==='published'?'Publisert':g.status==='rejected'?'Avvist':g.precision==='month'?'Tentativ måned · kontroller':'Venter på godkjenning'}</span></div>${g.status==='open'&&!g.error?`<div><div class="checkboxes">${demoGroups.filter(x=>x.active).map(x=>`<label><input type="checkbox" data-generated-group="${g.id}" value="${esc(x.code)}" ${x.code==='FA'?'checked':''}>${esc(x.code)}${x.code==='POL'?' – aktivt valg':''}</label>`).join('')}</div><div class="row-actions"><button type="button" class="primary" data-flow="approveGenerated" data-id="${g.id}">Godkjenn og publiser</button><button type="button" data-flow="rejectGenerated" data-id="${g.id}">Avvis</button></div></div>`:''}</div>`).join('')}</section>`:''}`};
runGeneration=function(){if(!moduleReady){notify('Årsmalen klargjøres. Prøv beregningen igjen om et øyeblikk.');return}moduleFrame.contentWindow.postMessage({type:'atelier:compute',year:workingYear},'*')};
publishGenerated=function(id){const g=generated.find(x=>x.id===id);if(!g||g.status!=='open'||g.error)return;const groups=[...document.querySelectorAll(`[data-generated-group="${id}"]:checked`)].map(n=>n.value);if(!groups.length){notify('Velg minst én synlighetsgruppe før godkjenning.');return}if(records.some(r=>r.id===id)){notify('Forslaget er allerede publisert.');return}records.push({id:g.id,title:g.title,date:g.date,budgetYear:g.budgetYear,precision:g.precision,category:g.category,note:'Konstruert eksempel, publisert fra årsmalen i skissen.',visibility:groups,published:true});g.status='published';render();notify('Forslaget er publisert. Kalender og Budsjettår viser den samme fristen med bevart datopresisjon.')};
// Faseforvaltning er flyttet, også fra de kontekstuelle snarveiene i tidslinjen.
openPhases=function(){if(!isAdmin)return;area='admin';section='settings';nextSettingsTab='phases';render()};
sharingView=function(){if(moduleTabs.sharing!=='data')return priorSharingView();backupKind='frister';const html=priorSharingView(),t=document.createElement('template');t.innerHTML=html;const select=t.content.querySelector('[name=backupKind]');if(select){select.innerHTML='<option value="frister">Publiserte frister</option>';backupKind='frister'}return t.innerHTML+'<section class="surface"><h2>Årsmal</h2><p>Gjentaksreglene har egen eksport og import under Årsmal. Det er samme regelsett som brukes ved generering.</p><button type="button" data-template-transfer>Åpne overføring av mal →</button></section>'};
window.addEventListener('message',e=>{if(e.source!==moduleFrame.contentWindow)return;const msg=e.data;if(msg?.type==='atelier:ready'){moduleReady=true;moduleFrame.contentWindow.postMessage({type:'atelier:init',state:moduleSnapshot,area:section==='settings'?'settings':'template',settingsTab:nextSettingsTab},'*');syncModule()}
 if(msg?.type==='atelier:state'){moduleSnapshot=msg.state;phases=structuredClone(msg.state.phases);phaseEnd=msg.state.phaseEnd}
 if(msg?.type==='atelier:height')moduleFrame.style.height=Math.min(12000,Math.max(600,msg.height+20))+'px';
 if(msg?.type==='atelier:navigate'){section=msg.area;area='admin';render()}
 if(msg?.type==='atelier:dialog'&&!moduleFrame.hidden)moduleFrame.scrollIntoView({block:'start',behavior:'smooth'});
 if(msg?.type==='atelier:computed'){generated=generated.filter(g=>g.budgetYear!==msg.year).concat(msg.results.map(r=>{const id='generated-'+msg.year+'-'+r.rule;return {...r,id,budgetYear:msg.year,groups:['FA'],status:r.error?'error':records.some(e=>e.id===id)?'published':'open'}}));render();notify('Årsmalen er beregnet for '+msg.year+'. Ingen nye frister er publisert. Godkjenn forslagene enkeltvis.')}
});
document.addEventListener('change',e=>{if(e.target.id==='workingYear'){workingYear=Number(e.target.value);registrySearch='';render()}});
document.addEventListener('input',e=>{if(e.target.id==='yearRegistrySearch'){registrySearch=e.target.value;const pos=e.target.selectionStart;render();const next=$('yearRegistrySearch');next.focus();next.setSelectionRange(pos,pos)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.yearTab){yearTab=b.dataset.yearTab;render()}if(b.dataset.workYear){workingYear=Number(b.dataset.workYear);yearTab='queue';render()}if(b.hasAttribute('data-template-preview')){section='template';nextModuleTab='try';render()}if(b.hasAttribute('data-template-transfer')){section='template';nextModuleTab='transfer';render()}if(b.hasAttribute('data-compute-year')){const open=generated.some(g=>g.budgetYear===workingYear&&g.status==='open');if(open)confirmWorkflow('Erstatt årets åpne genererte forslag?','Publiserte frister og de løpende forslagene beholdes. Bare årets åpne genererte forslag beregnes på nytt.','Beregn på nytt',runGeneration);else runGeneration()}});
render();

document.addEventListener('click',e=>{if(e.target.closest('[data-flow=documentQueue]'))workingYear=2027},true);
